import sys

def is_scramble(s1: str, s2: str, memo: dict) -> bool:
    if (s1, s2) in memo:
        return memo[(s1, s2)]

    if s1 == s2:
        memo[(s1, s2)] = True
        return True

    n = len(s1)
    if n == 0:
        return False

    if sorted(s1) != sorted(s2):
        memo[(s1, s2)] = False
        return False

    for i in range(1, n):
        if (is_scramble(s1[:i], s2[:i], memo) and is_scramble(s1[i:], s2[i:], memo)) or \
           (is_scramble(s1[:i], s2[n-i:], memo) and is_scramble(s1[i:], s2[:n-i], memo)):
            memo[(s1, s2)] = True
            return True

    memo[(s1, s2)] = False
    return False

def main():
    input_data = sys.stdin.read().strip().split('\n')
    if len(input_data) < 2:
        return
    s1 = input_data[0].strip()
    s2 = input_data[1].strip()

    memo = {}
    result = is_scramble(s1, s2, memo)

    if result:
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
    main()
